style.css:
@-moz-document domain("google.com"), domain("google.co.th") {
:root { color-scheme: light !important; }
  body {
    background: #f3eedc !important;
    color: #242820 !important;
    font-family: "Courier New", Tahoma, monospace !important;
  }
  body, input, textarea, button {
    font-family: "Courier New", Tahoma, monospace !important;
  }
  a { color: #143b77 !important; }
  a:visited { color: #6a3b70 !important; }
  a:hover { color: #00695f !important; text-decoration: underline !important; }
  h3 { font-family: Georgia, "Times New Roman", serif !important; }
  #search, #rso, #rhs, #main, #cnt, #appbar, #top_nav, #bottomads,
  #fbar, footer, .sfbg {
    background-color: #f3eedc !important;
    color: #242820 !important;
  }
  #fbar, footer {
    border-top: 3px double #7e8973 !important;
  }
  .RNNXgb, .aajZCb {
    background: #fffdf2 !important;
    color: #242820 !important;
    border: 2px solid #69766b !important;
    border-radius: 2px !important;
    box-shadow: inset 2px 2px 0 #c2c8b8, 4px 4px 0 #b3bcaa !important;
  }
  textarea[name="q"], input[name="q"] {
    color: #20291f !important;
    background: transparent !important;
    caret-color: #00695f !important;
  }
  input[type="submit"], input[type="button"], button[type="submit"] {
    color: #173c37 !important;
    background: #dedfc9 !important;
    border: 2px solid !important;
    border-color: #fffef2 #69766b #69766b #fffef2 !important;
    border-radius: 0 !important;
    box-shadow: 2px 2px 0 #a9b29e !important;
    font-weight: bold !important;
  }
  input[type="submit"]:active, button[type="submit"]:active {
    border-color: #69766b #fffef2 #fffef2 #69766b !important;
    box-shadow: none !important;
  }
  a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible {
    outline: 2px dashed #00695f !important;
    outline-offset: 4px !important;
  }
  .VwiC3b, .IsZvec, .YyVfkd, .ylgVCe, cite {
    color: #405443 !important;
  }
  ::selection { background: #00695f !important; color: #fffdf2 !important; }
  @media (max-width: 600px) {
    .RNNXgb { box-shadow: inset 2px 2px 0 #c2c8b8, 2px 2px 0 #b3bcaa !important; }
  }
}
